sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
layout(color) uniform half4 color;
uniform float blur;
uniform float width;
uniform float alpha;
uniform float fill;
uniform float count;
uniform float phase;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float b = float(blurred.eval(coord).a);
    float gx = float(blurred.eval(coord + float2(1.0, 0.0)).a - blurred.eval(coord - float2(1.0, 0.0)).a) * 0.5;
    float gy = float(blurred.eval(coord + float2(0.0, 1.0)).a - blurred.eval(coord - float2(0.0, 1.0)).a) * 0.5;
    float grad = max(length(float2(gx, gy)), 0.00001);
    float n = floor(count + 0.5);
    float line = 0.0;
    for (int i = 0; i < 10; i++) {
        if (float(i) >= n) break;
        float level = 0.48 * (1.0 - fract((float(i) + 0.5) / n + phase));
        float px = abs(b - level) / grad;
        line = max(line, clamp(width * 0.5 - px + 0.5, 0.0, 1.0));
    }
    line *= clamp(alpha, 0.0, 1.0) * float(color.a) * step(float(src.a), 0.999);
    half4 body = src * half(clamp(fill, 0.0, 1.0));
    half4 ring = half4(color.rgb, 1.0) * half(line);
    return ring + body * (1.0 - ring.a);
}
